// Simplified schema diagram for a simulation.
//
// Shows, at a glance, the tables generated by a simulation, each with its
// actual simulated row count, plus how they connect via foreign keys. It is the
// slimmed-down cousin of the inspection RelationshipsGraph: no per-column
// detail, just one "filas" line per table and the FK edges. Mermaid is loaded
// lazily on the client because it touches the DOM and bloats the initial JS
// bundle if imported up-front.

"use client";

import { useEffect, useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";

import { api, type SimulationRelationship } from "@/lib/api";

// Sanitise a name for use as a Mermaid entity id (same rules as the inspection
// graph): keep [a-zA-Z0-9_], replace the rest with underscores, and prefix with
// `T_` so digit-leading names don't break.
function sanitizeId(name: string): string {
  const safe = name.replace(/[^a-zA-Z0-9_]/g, "_");
  return /^[a-zA-Z]/.test(safe) ? safe : `T_${safe}`;
}

function buildErDiagram(
  tableSizes: Record<string, number>,
  relationships: SimulationRelationship[],
): string {
  const lines: string[] = ["erDiagram"];
  const ids = new Map<string, string>();
  for (const t of Object.keys(tableSizes)) ids.set(t, sanitizeId(t));
  // Tables that only appear in relationships still need an entity so the edges
  // have endpoints.
  for (const rel of relationships) {
    if (!ids.has(rel.parent)) ids.set(rel.parent, sanitizeId(rel.parent));
    if (!ids.has(rel.child)) ids.set(rel.child, sanitizeId(rel.child));
  }

  for (const [table, id] of ids) {
    const size = tableSizes[table];
    // The row count goes in the entity's alias (its box title) rather than an
    // attribute row: Mermaid's ER attributes can't hold a bare/quoted number
    // (it's lexed as a NUM/COMMENT, never an attribute name), so a titled box
    // is the only clean way to show "<tabla> · N filas" — no filler column.
    const label = (size != null
      ? `${table} · ${size.toLocaleString()} filas`
      : table
    ).replace(/"/g, "'");
    lines.push(`  ${id}["${label}"]`);
  }

  for (const rel of relationships) {
    const parent = ids.get(rel.parent)!;
    const child = ids.get(rel.child)!;
    const label = `"${rel.column}${rel.is_context ? " (contexto)" : ""}"`;
    // One parent has many children (standard FK direction).
    lines.push(`  ${parent} ||--o{ ${child} : ${label}`);
  }

  return lines.join("\n");
}

export function SimulationSchemaDiagram({
  simulationId,
  fallbackSizes,
  relationships,
}: {
  simulationId: string;
  /** Training row counts, used while the actual counts load or for tables that
   *  have no synthetic file yet (e.g. the run is still in progress). */
  fallbackSizes: Record<string, number>;
  relationships: SimulationRelationship[];
}) {
  const [error, setError] = useState<string | null>(null);
  const [svg, setSvg] = useState<string | null>(null);

  // Actual generated row counts per synthetic table. Returns {} (caught below)
  // for in-progress runs that have no synthetic data yet.
  const rowCountsQuery = useQuery({
    queryKey: ["simulation", simulationId, "synthetic-row-counts"],
    queryFn: async () => {
      const { data } = await api.get<Record<string, number>>(
        `/simulations/${simulationId}/synthetic-row-counts`,
      );
      return data;
    },
    retry: false,
  });
  const actualCounts = rowCountsQuery.data;
  const hasActualCounts = !!actualCounts && Object.keys(actualCounts).length > 0;

  // Prefer the real simulated counts; fall back to the training sizes per table.
  const tableSizes = useMemo(() => {
    const merged: Record<string, number> = { ...fallbackSizes };
    if (actualCounts) {
      for (const [table, count] of Object.entries(actualCounts)) {
        merged[table] = count;
      }
    }
    return merged;
  }, [fallbackSizes, actualCounts]);

  const tableCount = Object.keys(tableSizes).length;
  const diagram = useMemo(
    () => buildErDiagram(tableSizes, relationships),
    [tableSizes, relationships],
  );

  useEffect(() => {
    if (tableCount === 0) return;
    let cancelled = false;
    (async () => {
      try {
        const { default: mermaid } = await import("mermaid");
        mermaid.initialize({
          startOnLoad: false,
          theme: "neutral",
          securityLevel: "strict",
          er: { useMaxWidth: true },
        });
        const id = `sim-er-${Math.random().toString(36).slice(2)}`;
        const { svg } = await mermaid.render(id, diagram);
        if (!cancelled) setSvg(svg);
      } catch (e) {
        if (!cancelled) setError(e instanceof Error ? e.message : String(e));
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [diagram, tableCount]);

  if (tableCount === 0) return null;

  return (
    <div className="space-y-2">
      <h4 className="text-xs font-medium text-foreground">
        Esquema y tamaño de tablas
      </h4>
      {error && (
        <p className="text-xs text-destructive">
          No se pudo renderizar el diagrama: {error}
        </p>
      )}
      {svg ? (
        <div
          className="overflow-auto rounded-md border bg-card p-3"
          // Mermaid output is sanitised to inline SVG; safe to inject.
          dangerouslySetInnerHTML={{ __html: svg }}
        />
      ) : (
        !error && (
          <div className="rounded-md border bg-card p-3">
            <p className="text-xs text-muted-foreground">Generando diagrama…</p>
          </div>
        )
      )}
      <p className="text-[11px] text-muted-foreground">
        {tableCount} {tableCount === 1 ? "tabla" : "tablas"} · {relationships.length}{" "}
        {relationships.length === 1 ? "relación" : "relaciones"} ·{" "}
        {hasActualCounts
          ? "filas realmente simuladas"
          : "filas según el entrenamiento del modelo"}
      </p>
    </div>
  );
}
